<?php
/** Push approved FleetDesk database state into separate FleetDesk-owned tabs. */
if(PHP_SAPI!=='cli'){http_response_code(403);exit("CLI only.\n");}
require_once __DIR__.'/connection.php';require_once __DIR__.'/../includes/bootstrap.php';
$db=fleet_db();$enabled=$db->query("SELECT setting_value FROM system_settings WHERE setting_key='fleet_sheet_sync_enabled'")->fetchColumn();if(!filter_var((string)$enabled,FILTER_VALIDATE_BOOLEAN)){echo "Fleet Sheet sync is disabled; no spreadsheet writes performed.\n";exit(0);}
$service=getGoogleSheetsWriterService();$ids=['CONSOLIDATED_TRUCKS'=>SHEET_CONSOLIDATED_ID,'NGWERERE_21MILES'=>SHEET_NGWERERE_21MILES_ID];
$assets=$db->query("SELECT a.id,a.primary_identifier,t.type_name,a.make,a.model,a.manufacture_year,a.registration_status,a.is_active,y.yard_name,st.status_name,ai.source_note,a.updated_at FROM assets a JOIN asset_types t ON t.id=a.asset_type_id LEFT JOIN yards y ON y.id=a.current_yard_id LEFT JOIN asset_statuses st ON st.id=a.current_status_id LEFT JOIN asset_identifiers ai ON ai.asset_id=a.id AND ai.is_primary=1 ORDER BY a.id")->fetchAll();
$driverRows=$db->query("SELECT id,full_name,phone,is_active,updated_at FROM drivers ORDER BY id")->fetchAll();$yardRows=$db->query("SELECT id,yard_code,yard_name,location_description,is_active,updated_at FROM yards ORDER BY id")->fetchAll();
$assignmentRows=$db->query("SELECT da.id,a.primary_identifier,d.full_name,d.phone,da.assigned_from,da.assigned_to,da.notes,da.asset_id,ai.source_note FROM asset_driver_assignments da JOIN assets a ON a.id=da.asset_id JOIN drivers d ON d.id=da.driver_id LEFT JOIN asset_identifiers ai ON ai.asset_id=a.id AND ai.is_primary=1 ORDER BY da.id")->fetchAll();
$linkRows=$db->query("SELECT aa.id,h.primary_identifier horse,t.primary_identifier trailer,aa.attached_from,aa.attached_to,aa.notes,aa.head_asset_id,ai.source_note FROM asset_attachments aa JOIN assets h ON h.id=aa.head_asset_id JOIN assets t ON t.id=aa.trailer_asset_id LEFT JOIN asset_identifiers ai ON ai.asset_id=h.id AND ai.is_primary=1 ORDER BY aa.id")->fetchAll();
function fleetSheetOwner(array $row):string{$note=strtoupper((string)($row['source_note']??''));if(str_contains($note,'NGWERERE_21MILES'))return 'NGWERERE_21MILES';if(str_contains($note,'CONSOLIDATED_TRUCKS'))return 'CONSOLIDATED_TRUCKS';return preg_match('/21\s*MILES/i',(string)($row['yard_name']??''))?'NGWERERE_21MILES':'CONSOLIDATED_TRUCKS';}
$assetBuckets=['CONSOLIDATED_TRUCKS'=>[['FleetDesk asset ID','Identifier','Asset type','Make','Model','Year','Registration state','Active','Current yard','Current status','Source worksheet','Updated at']], 'NGWERERE_21MILES'=>[['FleetDesk asset ID','Identifier','Asset type','Make','Model','Year','Registration state','Active','Current yard','Current status','Source worksheet','Updated at']]];
foreach($assets as $a){$owner=fleetSheetOwner($a);$source=preg_match('/^([^\/]+)/',(string)($a['source_note']??''),$m)?$m[1]:'FLEETDESK';$assetBuckets[$owner][]= [(string)$a['id'],(string)$a['primary_identifier'],(string)$a['type_name'],(string)($a['make']??''),(string)($a['model']??''),(string)($a['manufacture_year']??''),(string)$a['registration_status'],(int)$a['is_active']?'Active':'Archived',(string)($a['yard_name']??''),(string)($a['status_name']??''),$source,(string)$a['updated_at']];}
$assignmentBuckets=[];$linkBuckets=[];foreach($ids as $code=>$id){$assignmentBuckets[$code]=[['Assignment ID','Asset','Driver','Phone','Assigned from','Assigned to','Notes','Active']];$linkBuckets[$code]=[['Link ID','Horse','Trailer','Attached from','Attached to','Notes','Active']];}
foreach($assignmentRows as $r){$owner=fleetSheetOwner(['source_note'=>$r['source_note'],'yard_name'=>'']);$assignmentBuckets[$owner][]= [(string)$r['id'],(string)$r['primary_identifier'],(string)$r['full_name'],(string)($r['phone']??''),(string)$r['assigned_from'],(string)($r['assigned_to']??''),(string)($r['notes']??''),$r['assigned_to']?'Ended':'Current'];}
foreach($linkRows as $r){$owner=fleetSheetOwner(['source_note'=>$r['source_note'],'yard_name'=>'']);$linkBuckets[$owner][]= [(string)$r['id'],(string)$r['horse'],(string)$r['trailer'],(string)$r['attached_from'],(string)($r['attached_to']??''),(string)($r['notes']??''),$r['attached_to']?'Ended':'Current'];}
$managed=['_FleetDesk_Assets'=>'assets','_FleetDesk_Assignments'=>'assignments','_FleetDesk_Horse_Trailer_Links'=>'links'];$results=[];
foreach($ids as $code=>$spreadsheetId){$meta=$service->spreadsheets->get($spreadsheetId,['fields'=>'sheets.properties(sheetId,title)']);$existing=[];foreach($meta->getSheets() as $sh)$existing[$sh->getProperties()->getTitle()]=(int)$sh->getProperties()->getSheetId();$requests=[];foreach($managed as $title=>$kind)if(!isset($existing[$title]))$requests[]=['addSheet'=>['properties'=>['title'=>$title,'gridProperties'=>['rowCount'=>2000,'columnCount'=>20]]]];if($code==='CONSOLIDATED_TRUCKS'){foreach(['_FleetDesk_Drivers'=>'drivers','_FleetDesk_Locations'=>'yards'] as $title=>$kind)if(!isset($existing[$title]))$requests[]=['addSheet'=>['properties'=>['title'=>$title,'gridProperties'=>['rowCount'=>1000,'columnCount'=>12]]]];}if($requests)$service->spreadsheets->batchUpdate($spreadsheetId,new GoogleServiceSheetsBatchUpdateSpreadsheetRequest(['requests'=>$requests]));
 $tables=['_FleetDesk_Assets'=>$assetBuckets[$code],'_FleetDesk_Assignments'=>$assignmentBuckets[$code],'_FleetDesk_Horse_Trailer_Links'=>$linkBuckets[$code]];if($code==='CONSOLIDATED_TRUCKS'){$tables['_FleetDesk_Drivers']=[['FleetDesk driver ID','Name','Phone','Active','Updated at']];foreach($driverRows as $r)$tables['_FleetDesk_Drivers'][]=[(string)$r['id'],(string)$r['full_name'],(string)($r['phone']??''),(int)$r['is_active']?'Active':'Inactive',(string)$r['updated_at']];$tables['_FleetDesk_Locations']=[['FleetDesk location ID','Code','Location','Description','Active','Updated at']];foreach($yardRows as $r)$tables['_FleetDesk_Locations'][]=[(string)$r['id'],(string)$r['yard_code'],(string)$r['yard_name'],(string)($r['location_description']??''),(int)$r['is_active']?'Active':'Inactive',(string)$r['updated_at']];}
 foreach($tables as $title=>$rows){$lastColumn=chr(64+count($rows[0]));$range="'".str_replace("'","''",$title)."'!A1:{$lastColumn}".count($rows);$service->spreadsheets_values->update($spreadsheetId,$range,new Google\Service\Sheets\ValueRange(['values'=>$rows]),['valueInputOption'=>'RAW']);$results[]=$code.'/'.$title.'='.max(0,count($rows)-1);}}
echo 'FleetDesk mirror updated: '.implode(', ',$results)."\n";
